{"path": "creative_intent.json", "content": "{
  "user_need": "警察男主绑定"犯罪预警系统"，能在凶手额头看到倒计时。他发现未婚妻（法医）额头显示"将在今晚23:00杀害你"。系统提示"不可更改"。他必须在12小时内破解这个"未来命案"，同时不能让她发现他在防备她。随着调查，他发现她杀他的动机是为了阻止他去救一个会导致更大灾难的证人（D20为理想牺牲）。12万字，高密度悬疑。",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["预警", "防备", "破解", "牺牲", "阻止", "绞杀"],
    "scene_elements": ["犯罪预警系统", "警察", "法医", "12小时倒计时", "未来命案", "证人保护"],
    "relationship_tension": [
      "未婚夫妻变成预定凶手与受害者",
      "信任与猜忌的拉锯",
      "两人都在试图牺牲自己救对方",
      "爱到极致却必须互相伤害"
    ],
    "user_preferences": {
      "desired_emotion": "极致虐心、命运悲剧、喘不过气的悲剧感",
      "forbidden": ["烂尾", "强行HE", "降智推理", "无脑甜"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D20",
    "x_axis_mode_name": "为理想献祭自己",
    "y_axis_tags": ["系统流", "刑侦悬疑", "规则怪谈"],
    "reaction_strength": "✷",
    "tension_stars": 5,
    "forbidden_elements": ["主角降智", "反派脸谱化", "强行大团圆", "逻辑硬伤", "感情线注水"],
    "x_axis_display": "未婚妻为阻止更大灾难而选择杀死最爱的人；男主为保护未婚妻而试图阻止她成为凶手——两人都在为对方献祭自己，却被命运绞杀",
    "y_axis_combination_effect": "系统流提供'不可更改'的宿命压迫感；刑侦悬疑提供12小时倒计时的高密度推理线；规则怪谈强化'违反规则必死'的恐惧氛围",
    "reaction_formula": "预知系统 × 不可更改的命运 × 电车难题 = 你越想救她，越是在杀她；你越想活，越是在杀更多人",
    "platform_fit": ["起点", "晋江", "长佩", "知乎盐选"]
  },
  "one_sentence_synopsis": "警察发现未婚妻将在12小时后杀死自己，破解真相后发现她是为了阻止他救一个会毁灭更多人的证人——两人都在牺牲自己救对方，却被命运绞杀。"
}
"}

